using System.IO;

public class ReportExporter
{
    public void GenerateReport(SummaryReport report, bool exportCsv = false, string filePath = null)
    {
        // Existing functionality: Output summary report to console
        Console.WriteLine("Report Summary:");
        Console.WriteLine(report.ToString());

        // Additional feature: Export report in CSV format if requested
        if (exportCsv)
        {
            if (string.IsNullOrEmpty(filePath))
            {
                filePath = "report_output.csv";
            }

            try
            {
                using (StreamWriter writer = new StreamWriter(filePath))
                {
                    // Write CSV header
                    writer.WriteLine("Field,Value");

                    // Assuming SummaryReport has a method or properties to extract data
                    // For demonstration, we'll assume report has a method GetReportData() 
                    // that returns a dictionary or similar structure. 
                    // If not, you would need to adapt this to the actual structure of SummaryReport.

                    // Example: If report has properties like Title, Date, Content
