                    // writer.WriteLine($"Date,{report.Date}");

                    // Generic fallback: If report implements IEnumerable or has known fields,
                    // you would iterate and write them. Here we use ToString() as a placeholder
                    // for actual CSV conversion logic which depends on the SummaryReport structure.
                    // A proper implementation would map specific fields to CSV columns.

                    // For this example, we'll write a simple representation.
                    // In a real scenario, you'd parse report.ToString() or access specific properties.
                    writer.WriteLine($"Summary,{report.ToString().Replace(",", ";").Replace("\n", " ")}");
                }
                Console.WriteLine($"Report exported to CSV: {filePath}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error exporting report to CSV: {ex.Message}");
            }
        }
    }
}

